-- =============================================================
-- 00008_seed_gcp_ace_m5.sql
-- GCP ACE 練習問題 第2セット（m5q prefix）
-- =============================================================

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb, v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('m5q01', 'IAM・組織ポリシー',
   '異なるGCPプロジェクトに存在する2つのCompute EngineインスタンスをプライベートIPアドレスで直接通信させる必要があります。最小限の手順で実現するにはどれを組み合わせるべきですか？（2つ選択）',
   NULL::text,
   '["両プロジェクトのVPCをVPCピアリングで接続する","Cloud InterconnectとVPN Gatewayを組み合わせて使用する","両プロジェクトのVMが同一サブネットを使用できるよう共有VPCを設定する","各プロジェクトに独立したCloud NATを設定する"]',
   0, '[0,2]', 'multi',
   '{"asked":"異なるプロジェクト間でプライベートIP通信を実現する方法として、VPCピアリングと共有VPCの2つのアプローチを理解しているかを問う。","terms":[["VPCピアリング（VPC Peering）","2つのVPCを相互接続してプライベートIPアドレスで通信できるようにする機能。異なるプロジェクト・異なる組織間でも可能。ただし推移的ピアリングは不可。"],["共有VPC（Shared VPC）","1つのホストプロジェクトのVPCを複数のサービスプロジェクトで共有する機能。サービスプロジェクトのVMが同じサブネットを使える。組織内のプロジェクト間管理に優れる。"]],"think":"2つのアパート（プロジェクト）を繋げる方法は2種類。『廊下を繋げる（VPCピアリング）』か、最初から『同じマンション（共有VPC）』にするか。どちらもプライベートIPで直接通信できる。Cloud InterconnectはオンプレミスとGCPの接続で、Cloud NATは外部IP不要のアウトバウンド通信のため、プロジェクト間通信とは無関係。","vs":"VPCピアリングは対等な2つのVPCを繋げる。共有VPCはホストプロジェクトが所有するVPCを貸し出す。どちらもプライベートIP通信を実現できる。選択肢Bは過剰装備、選択肢Dは全く別の機能。","opt":["正解。VPCピアリングで2プロジェクトのVPCを接続しプライベートIP通信を実現。","Cloud InterconnectはオンプレミスとGCP間の専用線。プロジェクト間通信には不要。","正解。共有VPCで異なるプロジェクトのVMが同一サブネットを共有してプライベートIP通信。","Cloud NATは外部IP無しでインターネットにアウトバウンド接続する機能でプロジェクト間通信とは無関係。"]}'),

  ('m5q03', 'データベース・データ分析',
   'オンプレミスのMySQLデータベースをGoogle Cloud SQLに移行する際、ダウンタイムを最小限に抑えたい。どうすべきか？',
   NULL::text,
   '["Database Migration Service（DMS）を使用してCloud SQLへの継続的なレプリケーションを設定し、移行準備ができたらカットオーバーする","mysqldumpでデータをエクスポートしてGCSにアップロードし、Cloud SQL Importで一括インポートする","Cloud Dataflowパイプラインを作成してオンプレミスMySQLからCloud SQLへデータをストリーミングする","Cloud ComposerでAirflowワークフローを作成してバッチETLで移行する"]',
   0, '[0]', 'single',
   '{"asked":"GCPのDatabase Migration Service（DMS）がどういう場合に使われるかを理解しているかを問う。ダウンタイム最小化のための継続的レプリケーション手法を知っているか。","terms":[["Database Migration Service（DMS）","オンプレミスやクラウドのデータベースをCloud SQLに移行するためのマネージドサービス。継続的なレプリケーション（CDC: Change Data Capture）でダウンタイムを最小化したカットオーバーが可能。"],["カットオーバー","移行元から移行先への切り替え作業。DMSは継続レプリケーションにより、切り替え直前のデータも同期されるためダウンタイムが秒単位まで短縮できる。"]],"think":"お店（サービス）を閉めずに引越しするには、新しい店舗（Cloud SQL）でも同時に営業できるよう準備しながら（継続レプリケーション）、最後の一瞬だけ看板を付け替える（カットオーバー）のが最速。mysqldumpは一度シャッターを閉めて（サービス停止）から荷物を運ぶ方法でダウンタイムが長い。","vs":"mysqldump/Importは確実だがサービス停止が必要。DataflowはカスタムETL向けで移行専用ではなく設定が複雑。Cloud ComposerはバッチETLで同様にダウンタイムが発生する。","opt":["正解。DMSの継続的レプリケーション+カットオーバーがダウンタイム最小化の標準的手法。","mysqldump/ImportはダウンタイムなしではできないためMySQLのサービス停止が必要。","Dataflowは大規模データ変換向けで、単純なDB移行にはオーバースペックで設定も複雑。","Cloud ComposerはETLオーケストレーション向け。ダウンタイム最小化の移行には不向き。"]}'),

  ('m5q09', 'App Engine・Cloud Run',
   'App Engine Standardでホストしているアプリがあります。ユーザーの1%に新しいテストバージョンを見せたい。複雑さを最小限に抑えたい。どうすべきか？',
   NULL::text,
   '["同じアプリに新バージョンをデプロイし、GCPコンソールでトラフィック分割を設定する","App Engineの代わりにGKEにデプロイしてカナリアリリースを実装する","ロードバランサを設定して1%のリクエストを新バージョンに転送する","Cloud Armorで1%のユーザーIPをフィルタリングして新バージョンのURLに誘導する"]',
   0, '[0]', 'single',
   '{"asked":"App Engine Standardの組み込みトラフィック分割機能を知っているかを問う。サービスの切り替えに外部ツールが不要なことを理解しているか。","terms":[["App Engine トラフィック分割","App Engineに組み込まれた機能。同一サービスの複数バージョン間でトラフィックを割合で分配できる。gcloudコマンドまたはGCPコンソールから設定可能。"],"think":"App Engineは最初から『試食コーナー（トラフィック分割）』が内蔵されている。新商品（新バージョン）を1%のお客さんに試してもらうのはボタン一つ。GKEやロードバランサを別途用意するのは大げさで、App Engineならではの便利な機能を無視している。","vs":"GKEへの移行はプラットフォーム全体の変更でコストが高い。ロードバランサ設定は外部サービスを追加する余計な手順。Cloud Armorは特定IPのブロック/許可用でトラフィック分割ではない。","opt":["正解。App Engineの組み込みトラフィック分割で最小手順。","GKEへの移行はプラットフォーム変更で複雑さが大幅に増す。","App Engine前段にLBを追加するのは不要な複雑さを生む。App Engineの機能で十分。","Cloud ArmorはIPベースのセキュリティルール適用ツールで、割合ベースのトラフィック分割ではない。"]}'),

  ('m5q10', 'GKE',
   'GKEクラスタで動作するアプリケーションPodがCloud Storage APIに安全にアクセスする必要がある。サービスアカウントキーファイルを使わずに実現するには？',
   NULL::text,
   '["Workload Identityを有効化し、KubernetesサービスアカウントとIAMサービスアカウントをバインドする","Pod仕様にimagePullSecretsとして認証情報を設定する","GKEノードのサービスアカウントにCloud Storageへのフルアクセスを付与する","PodのenvとしてGOOGLE_APPLICATION_CREDENTIALSにサービスアカウントJSONをBase64エンコードで設定する"]',
   0, '[0]', 'single',
   '{"asked":"GKEでのWorkload Identityを使ったKeyレスアプリケーション認証の仕組みを理解しているかを問う。","terms":[["Workload Identity","GKEのPodがサービスアカウントキーファイルを使わずにGoogle Cloud APIに認証できる機能。KubernetesのサービスアカウントとGCPのIAMサービスアカウントを紐づける。Googleが推奨するGKEからのGCP API認証方法。"],["KSA/GSAバインディング","KSA（Kubernetes Service Account）とGSA（Google Service Account）のアノテーションによる関連付け。PodがKSAで動作するだけで対応するGSAの権限でGCP APIを利用できる。"]],"think":"社員証（KSA）を社内システムのIDカード（GSA）に紐付けるイメージ。財布（JSONキーファイル）を渡さなくても会社の設備を使えるように自動認証される。ノード全体に広い権限を与えるのは、社員全員に管理者権限を与えるようなもので危険。","vs":"ノードのSAにフルアクセスはそのノード上の全Podが広い権限を得てしまい最小権限の原則に反する。JSONキーをBase64エンコードで環境変数に入れるのもキー漏洩リスクがありGoogle非推奨。","opt":["正解。Workload IdentityはGKEからのキーレス認証のGoogleベストプラクティス。","imagePullSecretsはコンテナイメージのプル認証用でGCP API認証とは無関係。","ノードSAへのフルアクセス付与はそのノード上の全Podが対象となり最小権限の原則に反する。","環境変数にキーJSONを入れるのはキーが露出するリスクがあり、Workload Identityを使うべき。"]}'),

  ('m5q11', 'IAM・組織ポリシー',
   '組織全体でCloud Storageバケットが公開アクセス可能な状態にならないようにしたい。新しく作成されるすべてのバケットに自動的に適用したい。どうすべきか？',
   NULL::text,
   '["Organization Policyで「constraints/storage.publicAccessPrevention」を組織レベルで強制する","各プロジェクトのCloud Storageバケット設定で手動でUniform bucket-level accessを有効にする","IAMでAllUsersとAllAuthenticatedUsersへのStorage Object Viewerロール付与を禁止するカスタムロールを作成する","Cloud Monitoringでバケットのアクセス設定を監視してアラートを設定する"]',
   0, '[0]', 'single',
   '{"asked":"GCPの組織ポリシー（Organization Policy）で特定の設定を組織全体に強制できることを理解しているかを問う。","terms":[["組織ポリシー（Organization Policy）","組織・フォルダ・プロジェクトレベルでGCPリソースの設定に制約を課すサービス。IAMのロール付与ではなくリソースの設定自体を制限できる。"],["constraints/storage.publicAccessPrevention","Cloud StorageバケットのallUsers/allAuthenticatedUsersへのアクセスを禁止するポリシー制約。新規・既存バケット問わず公開設定を強制的にブロックする。"]],"think":"マンション（組織）のルール（組織ポリシー）で「玄関の鍵は必ずかけること」を全部屋（バケット）に強制する。後から個別部屋（プロジェクト）で鍵を開けようとしても、ルールが優先されて開けられない。監視カメラ（Monitoring）は鍵を開けたことを知らせるだけで防止はできない。","vs":"手動設定は各プロジェクトへの適用漏れが生じる。カスタムロールはIAM割り当てに対する制御で、既存の設定を変更するポリシーとは別。Monitoringは事後検知で予防ではない。","opt":["正解。組織ポリシーで制約を強制すれば新規・既存すべてのバケットに自動適用される。","手動設定は各プロジェクトに対して行う必要があり適用漏れが生じる。","カスタムロールはIAMロールの内容を変えるもので、バケットの設定を直接変えるポリシーとは仕組みが違う。","Monitoringは事後検知のみで、公開状態の作成を予防する機能はない。"]}'),

  ('m5q12', 'データベース・データ分析',
   'Cloud StorageバケットにCSVファイルがある。毎日新しいファイルが追加され、BigQueryで即座にクエリできるようにしたい。ファイルをBigQueryに移動したくない。どうすべきか？',
   NULL::text,
   '["Cloud StorageバケットをソースとするBigQuery外部テーブル（External Table）を作成する","Cloud Dataflowパイプラインでファイルを自動的にBigQueryにロードする","Cloud Functionsでファイル追加をトリガーにBigQueryのbq loadコマンドを実行する","BigQuery Data Transfer Serviceを使用してCloud StorageからBigQueryに毎日データを転送する"]',
   0, '[0]', 'single',
   '{"asked":"BigQueryの外部テーブル機能でCloud Storage上のファイルをBigQueryに移動せずにSQLでクエリできることを知っているかを問う。","terms":[["BigQuery外部テーブル（External Table）","GCS・Google Drive・Bigtable上のデータをBigQueryに読み込まずにSQLクエリできる機能。データはBigQueryには保存されず、元のソースに留まる。コスト効率が高い。"],["Federated Query（フェデレーテッドクエリ）","外部テーブルと同様の概念。BigQueryがGCS上のファイルを直接スキャンしてSQLで処理する。"]],"think":"本（CSV）を図書館（BigQuery）に所蔵しなくても、図書館のカタログ（外部テーブル）に登録するだけで読めるイメージ。実物は元の棚（GCS）にある。毎日新しい本（ファイル）が追加されても、カタログが自動的に見つけてくれる（GCSのワイルドカードURLを指定）。","vs":"Dataflow/Cloud Functions/Data Transfer Serviceはすべてデータをコピー・移動する方法で、「ファイルをBigQueryに移動したくない」という要件に反する。","opt":["正解。外部テーブルはデータをコピーせずBigQueryでSQLクエリできる最も直接的な方法。","DataflowはBigQueryにデータをロードしてしまうため要件に反する。","Cloud Functionsはbq loadを呼んでデータをBigQueryにコピーするため要件に反する。","Data Transfer Serviceはスケジュール転送でデータをBigQueryにコピーするため要件に反する。"]}'),

  ('m5q20', 'データベース・データ分析',
   'Cloud SQL for PostgreSQLを本番環境で使用している。ゾーン障害が発生した際に自動フェイルオーバーを実現したい。どうすべきか？',
   NULL::text,
   '["Cloud SQLインスタンスで高可用性（High Availability）を有効にして、スタンバイインスタンスを別ゾーンに配置する","同一リージョンの別ゾーンにリードレプリカを作成し、障害時に手動でプロモートする","Cloud SQLを複数リージョンにデプロイしてCloud Load Balancerで振り分ける","Cloud Spannerに移行して自動的なマルチゾーン耐障害性を利用する"]',
   0, '[0]', 'single',
   '{"asked":"Cloud SQLの高可用性（HA）設定によるゾーン障害時の自動フェイルオーバーを理解しているかを問う。リードレプリカとHAの違いも問われる。","terms":[["Cloud SQL HA（高可用性）","プライマリインスタンスと同期スタンバイインスタンスを別ゾーンに配置する構成。プライマリが障害を起こすと自動的にスタンバイに切り替わる（フェイルオーバー）。接続文字列の変更は不要。"],["リードレプリカ","読み取り専用のレプリカ。主に読み取り負荷分散に使う。フェイルオーバーはできるが、手動でのプロモートが必要。自動フェイルオーバーはできない。"]],"think":"本番サーバー（プライマリ）が故障した時、自動的に副サーバー（スタンバイ）に切り替わる仕組みがHA。リードレプリカは副サーバーがあるけど切り替えは手動。自動フェイルオーバー=HA設定の有効化が最短手順。","vs":"リードレプリカは手動プロモートが必要なため「自動フェイルオーバー」の要件を満たさない。Cloud SQLはマルチリージョンLBに対応していない。Spannerへの移行はアーキテクチャ変更で大規模な作業が必要。","opt":["正解。HA設定で同期スタンバイを別ゾーンに配置し自動フェイルオーバーを実現。","リードレプリカへのフェイルオーバーは手動操作が必要で自動フェイルオーバーにならない。","Cloud SQLはLB経由でのマルチリージョン接続を標準サポートしていない。","Spannerへの移行は大規模なアーキテクチャ変更で、PostgreSQL互換性も異なる。"]}'),

  ('m5q22', '監視・ログ',
   'GCPプロジェクトのCompute EngineインスタンスのCPU使用率が80%を超えた場合にSlackに通知を送りたい。どうすべきか？',
   NULL::text,
   '["Cloud Monitoringでアラートポリシーを作成しNotification Channelとして「Webhooks」を使用してSlackのIncoming Webhook URLを設定する","Cloud Loggingでシンクを作成してPub/SubトピックにルーティングしCloud FunctionsでSlackに通知する","GCPコンソールのCompute Engine画面でCPU使用率を手動で定期確認してSlackに報告する","Cloud Schedulerで定期的にgcloudコマンドを実行してCPU使用率を取得しSlackに通知するCloud Functionsを呼び出す"]',
   0, '[0]', 'single',
   '{"asked":"Cloud MonitoringのアラートポリシーとNotification Channelを使ってメトリクスベースのアラートを設定する方法を理解しているかを問う。","terms":[["Cloud Monitoring アラートポリシー","特定のメトリクス（CPU使用率など）が閾値を超えた場合に通知を送るルールを定義する機能。条件・通知チャネル・アラート設定を一元管理。"],["Notification Channel","アラートの通知先を定義する設定。Email・Slack・PagerDuty・Webhookなど多数のチャネルをサポート。SlackはWebhookまたは直接のSlackインテグレーションで設定可能。"]],"think":"温度センサー（Monitoring）が設定温度（80%）を超えたら警報（アラートポリシー）が鳴り、担当者（Slack）に自動連絡される仕組み。わざわざ毎回確認したり（手動）、別の複雑な経路（Logging→Pub/Sub→Functions）を通す必要はない。","vs":"Logging→Pub/Sub→Functionsはメトリクスではなくログベースのアラートに適した構成で余分な手順が多い。手動確認とSchedulerはリアルタイム性がなく実用的でない。","opt":["正解。Cloud MonitoringのアラートポリシーとWebhook通知チャネルが最も直接的な方法。","メトリクスベースのアラートにLogging経由は不要な複雑さを生む。ログシンクはログデータの転送に使う。","手動確認はリアルタイム検知にならず、人的ミスも生じる。","定期ポーリングはリアルタイムではなくCloud Schedulerの実行間隔分だけ遅延が発生する。"]}'),

  ('m5q23', 'ネットワーキング',
   'GCPのVPCでCompute Engineインスタンスのネットワークトラフィックをモニタリングしたいエンジニアがいます。どのソースIP/宛先IP間のフローが発生しているかを調べたい。どうすべきか？',
   NULL::text,
   '["VPCサブネットでVPCフローログを有効化し、Cloud Loggingで確認する","Compute Engineインスタンス上でtcpdumpを実行してネットワークキャプチャを行う","Cloud Monitoringでネットワークのin/outバイト数をモニタリングするダッシュボードを作成する","Packet Mirroringを設定してすべてのトラフィックをコレクターVMにミラーリングする"]',
   0, '[0]', 'single',
   '{"asked":"VPCフローログの機能と用途を理解しているかを問う。フロー情報（IP/ポート/バイト数）の確認にはVPCフローログが適していることを知っているか。","terms":[["VPCフローログ","VPCサブネット内のネットワークインターフェースを通過するトラフィックのフロー情報（送信元/宛先IP・ポート・バイト数・プロトコル）をログとして記録する機能。Cloud Loggingに保存されBigQueryで分析可能。"],["Packet Mirroring","VMのネットワークトラフィックをパケットレベルでキャプチャして別のVMに転送する機能。深いパケット検査（DPI）に使う。フローログより粒度が細かいがコストも高い。"]],"think":"どのお客さん（IP）がどの窓口（ポート）を使ったか記録する受付台帳がVPCフローログ。tcpdumpは直接VMにアクセスして手紙（パケット）の中身まで読む方法で手間がかかる。フロー情報（誰が誰と通信したか）を知るだけならフローログで十分。","vs":"tcpdumpはVMへのSSHアクセスが必要で管理コストが高い。Cloud Monitoringは集計値（総バイト数）のみで個々のフロー情報は得られない。Packet Mirroringはパケットレベルの詳細解析向けでフロー確認のみには過剰。","opt":["正解。VPCフローログでサブネットのフロー情報をCloud Loggingで分析できる。","tcpdumpは各VMへのSSHが必要で大規模環境では非効率。","Monitoringのメトリクスは集計値でフロー単位（誰が誰と通信したか）の情報は取れない。","Packet Mirroringはパケット内容の深い検査向けでIPフロー確認のみには過剰なコスト。"]}'),

  ('m5q25', 'App Engine・Cloud Run',
   'コンテナ化されたステートレスなHTTP APIを最小限の管理コストでスケーラブルにデプロイしたい。リクエストがない時はゼロにスケールダウンさせたい。どうすべきか？',
   NULL::text,
   '["Cloud Runを使用してコンテナイメージをデプロイする","GKEクラスタを作成してDeploymentとServiceを設定する","App Engine Standardでコンテナをデプロイする","Compute Engineのマネージドインスタンスグループにコンテナをデプロイする"]',
   0, '[0]', 'single',
   '{"asked":"Cloud Runのサーバーレスコンテナ実行環境の特性（ゼロスケール・フルマネージド・コンテナ対応）を理解し、適切なユースケースで選べるかを問う。","terms":[["Cloud Run","フルマネージドなサーバーレスコンテナ実行環境。リクエストがない時はゼロインスタンスに自動スケールダウンし、コスト不要。コンテナイメージをデプロイするだけで動作する。インフラ管理が一切不要。"],["ゼロスケール（Scale to zero）","トラフィックがない時にインスタンス数を0にしてコストをゼロにする機能。Cloud RunとCloud Functionsはデフォルトで対応。"]],"think":"自動販売機（Cloud Run）はお客さんが来た時だけ電源が入って商品を出す。誰も来ない夜中は電源ゼロ。GKEは常時電気（クラスタ）が必要で管理コストも高い。App Engine Standardもサーバーレスだがコンテナのカスタマイズ性が低い。","vs":"GKEは強力だが、クラスタ管理・設定コストが高く「最小限の管理コスト」に反する。App Engineはランタイムに制約がある。MIGはVMベースでコンテナネイティブでない上、スケールダウンはゼロにならない。","opt":["正解。Cloud Runはゼロスケール・フルマネージド・コンテナ対応で要件に完全一致。","GKEはクラスタ管理が必要で「最小限の管理コスト」に反する。ゼロスケールは標準設定では不可。","App Engineはコンテナをそのままデプロイする形式ではなく、ランタイムに制約がある。","MIGはVMベースでコンテナを直接実行する場合は追加設定が必要。ゼロインスタンスへのスケールダウンもできない。"]}'),

  ('m5q29', 'データベース・データ分析',
   'Cloud Spannerのテーブルでプライマリキーに連番（AUTO INCREMENT）を使用しようとしている。この設計の問題点と推奨される代替策は何か？',
   NULL::text,
   '["連番プライマリキーはSpannerでホットスポットを引き起こす。代わりにUUID（ランダムな値）またはビット反転（bit_reverse）したキーを使用すべき","連番はSpannerでは使用できないため、タイムスタンプをプライマリキーとして使用すべき","連番プライマリキーはパフォーマンスに問題ないが、UUIDに変更すると読み取り速度が向上する","連番はSpannerで最も効率的なプライマリキー設計で変更は不要"]',
   0, '[0]', 'single',
   '{"asked":"Cloud Spannerの分散アーキテクチャにおけるホットスポット問題と、それを回避するためのキー設計を理解しているかを問う。","terms":[["ホットスポット（Hotspot）","Spannerのデータが特定のサーバー（スプリット）に偏って書き込みが集中する現象。連番やタイムスタンプを昇順でプライマリキーにすると発生しやすい。書き込みパフォーマンスが大幅に低下する。"],["bit_reverse / UUID","ホットスポットを防ぐためのキー設計。ビット反転で連番の偏りを分散させるか、完全ランダムなUUIDを使う。Spannerはデータをキーの順序でサーバーに分散させるため、ランダムなキーは均等な負荷分散につながる。"]],"think":"荷物（データ）を倉庫（Spanner）の棚（サーバー）に配置するとき、連番ラベル（1,2,3...）にすると最新の棚（一番大きい番号の棚）に集中して大渋滞。ランダムラベル（UUID）にすれば全棚に均等に分散して効率的。","vs":"タイムスタンプも昇順なのでホットスポットになる。連番が使えないのではなく、設計上避けるべきもの。読み取り速度とは直接関係ない（書き込みホットスポットが問題）。","opt":["正解。連番はホットスポットを引き起こすのでUUIDかbit_reverseが推奨。","タイムスタンプも昇順なのでホットスポット問題は同じ。Spannerに使えないわけではなく非推奨。","読み取り速度の問題ではなく書き込みの分散が主な問題。パフォーマンスに無関係ではない。","連番は最も非推奨のキー設計。Spannerの分散アーキテクチャと相性が悪い。"]}'),

  ('m5q30', 'ネットワーキング',
   '既存のVPCのサブネットのIPアドレスが枯渇してきた（/28サブネット）。新しいVMを追加するためにIPアドレスを増やしたい。どうすべきか？',
   NULL::text,
   '["gcloudコマンドまたはGCPコンソールで既存サブネットのIP範囲を拡張する（サブネット拡張）","既存サブネットを削除して/24サブネットを新しく作成する","既存VPCに新しいサブネットを追加して新しいVMをそちらに配置する","プロジェクト全体を新しいVPCに移行してより大きいIPアドレス空間を確保する"]',
   0, '[0]', 'single',
   '{"asked":"GCPのVPCサブネット拡張機能（expand subnet）を知っているかを問う。既存サブネットを削除・再作成せずにIP範囲を拡張できることを理解しているか。","terms":[["サブネット拡張（Subnet Expansion）","既存のサブネットのIPv4 CIDR範囲を大きくする操作。gcloud compute networks subnets expand-ip-rangeコマンドで実行。縮小はできないが拡張は非破壊的で既存VMへの影響なし。"],["CIDR /28","16個のIPアドレス（GCPは4つを予約するため実質12個が使用可能）のサブネット。/28→/24に拡張すると256個（実質252個）になる。"]],"think":"部屋（サブネット）が手狭になったら、壁を壊して広げる（サブネット拡張）のが一番シンプル。引越し（削除・再作成）すると既存の家具（VM）も全部動かさなければいけないので大変。隣に別の部屋（新サブネット）を作るのも悪くないが、既存VMのIPは変わらず管理が複雑になる。","vs":"サブネット削除→再作成は既存VMが全て削除される破壊的な操作。新サブネットの追加は可能だが、既存VMのIPは変わらず管理が複雑になる場合がある。VPC移行は最も大規模で破壊的な手順。","opt":["正解。サブネット拡張は非破壊的で既存VMに影響なく最小限の手順でIPアドレスを増やせる。","サブネット削除・再作成は既存VMを全て削除する破壊的操作で要件に適さない。","新サブネット追加も選択肢だが、既存VMはIPが変わらず管理が分散する。拡張の方がシンプル。","プロジェクト全体のVPC移行は最も複雑で影響範囲が大きい。最後の手段。"]}'),

  ('m5q31', 'IAM・組織ポリシー',
   '複数のGCPプロジェクトにまたがるCompute Engineインスタンスの一覧を定期的に取得するスクリプトを作成したい。どうすべきか？',
   NULL::text,
   '["gcloud config configurationsで複数の構成を作成し、スクリプトで各構成をアクティブに切り替えながらgcloud compute instances listを実行する","各プロジェクトに個別にSSHしてVMのリストを取得するスクリプトを実行する","GCPコンソールのCompute Engineページでプロジェクトごとに手動でリストを確認する","Cloud Schedulerで各プロジェクトのBilling APIを呼び出してリソース使用状況を確認する"]',
   0, '[0]', 'single',
   '{"asked":"gcloudコマンドの複数プロジェクト管理機能（configuration）を使って複数プロジェクトをスクリプトで操作する方法を理解しているかを問う。","terms":[["gcloud configurations","gcloudツールの設定プロファイル。アカウント・プロジェクト・リージョン等をまとめて保存できる。複数の構成を切り替えることで、複数プロジェクトに対して同じコマンドを実行できる。"],["gcloud config configurations activate","指定した構成をアクティブにするコマンド。スクリプト内でこれを呼び出した後にgcloud computeコマンドを実行すると、その構成のプロジェクトに対して操作が行われる。"]],"think":"複数のオフィス（プロジェクト）の在庫確認をするとき、各オフィスの合鍵（configuration）を持っておいて順番に使えば、いちいち新しい鍵を作らなくてもいい。SSHで各VMに直接入るのはVMが何十台もあると大変。手動確認はスクリプト化にならない。","vs":"個別SSHは各VMにアクセスが必要で数が増えると非効率。手動確認はスクリプト自動化にならない。Billing APIはコスト情報を取得するもので、インスタンス一覧の取得ではない。","opt":["正解。gcloud configurationsで各プロジェクトの設定を切り替えながらスクリプトで自動化できる。","各VMへのSSHは管理対象が増えると非効率で、インスタンス一覧取得の目的に対して過剰な手順。","手動確認はスクリプト自動化の要件を満たさない。","Billing APIはコスト・使用量データ取得用でインスタンス一覧の取得とは異なる。"]}'),

  ('m5q37', 'GKE',
   'GKEクラスタのMLワークロードにGPUを追加したい。既存のCPUワークロードのクラスタを使いながらMLチームだけがGPUを使えるようにしたい。どうすべきか？',
   NULL::text,
   '["新しいGPU対応ノードプールをGKEクラスタに追加し、MLチームのPodにcloud.google.com/gke-accelerator: nvidia-tesla-p100のnodeSelectorを設定する","既存のノードをGPU搭載に変更して全チームが使えるようにする","GPU専用の独立したGKEクラスタを作成してMLチームに提供する","GKEの代わりにCompute EngineのGPUインスタンスをMLチームに直接提供する"]',
   0, '[0]', 'single',
   '{"asked":"GKEのノードプールとnodeSelectorを使って特定のワークロードを特定のノードタイプに配置する方法を理解しているかを問う。","terms":[["ノードプール（Node Pool）","GKEクラスタ内の同じ設定（マシンタイプ・GPUなど）を持つノードのグループ。クラスタに複数のノードプールを追加して異なる種類のワークロードに対応できる。"],["nodeSelector","KubernetesのPod仕様で、Podを特定のラベルを持つノードにのみスケジューリングする設定。cloud.google.com/gke-accelerator: nvidia-tesla-p100と指定するとGPU搭載ノードにのみ配置される。"]],"think":"工場（クラスタ）に特殊な機械（GPUノードプール）を追加して、その機械を使う仕事（MLワークロード）だけが使えるように予約番号（nodeSelector）を設定するイメージ。工場全体を作り直す（新クラスタ）のは無駄が多く、既存機械（CPUノード）を全部特殊機械に替えると普通の仕事ができなくなる。","vs":"既存ノードのGPU変更は不可能（ノードのマシンタイプは変更できない）。独立クラスタは管理コストが増加。Compute Engineの直接提供はKubernetes管理の利点を失う。","opt":["正解。GPU対応ノードプールの追加とnodeSelectorで既存クラスタを活かしながらGPUを特定ワークロードに限定できる。","既存ノードのマシンタイプは変更不可。全員にGPUを解放するのも要件に反する。","独立クラスタはオーバーヘッドが大きく、既存クラスタとの連携も複雑になる。","Compute Engineの直接提供はKubernetesの自動スケーリング・リソース管理の恩恵を受けられない。"]}'),

  ('m5q38', 'ストレージ',
   'Cloud StorageバケットにあるオブジェクトをComliance要件で7年間変更・削除できないようにしたい。どうすべきか？',
   NULL::text,
   '["Cloud StorageバケットにRetention Policy（保持ポリシー）を設定し、保持期間を7年間に指定する","バケットのIAMポリシーでAllUsersの削除権限を取り消す","バケットのライフサイクルルールで7年後にオブジェクトを削除するルールを追加する","Cloud KMSを使用してオブジェクトを暗号化し、管理者のみが鍵にアクセスできるようにする"]',
   0, '[0]', 'single',
   '{"asked":"Cloud StorageのRetention Policyでオブジェクトの変更・削除を一定期間禁止できることを理解しているかを問う。コンプライアンス要件のためのImmutabilityを知っているか。","terms":[["Retention Policy（保持ポリシー）","Cloud Storageバケットに設定する、オブジェクトを指定期間変更・削除できなくする機能。設定後は管理者でも削除できない（Locked状態にすると設定自体も変更不可）。コンプライアンス・法的要件に対応する。"],["Object Retention Lock","オブジェクト単位で保持期間を設定する機能（バケット単位のRetention Policyとは別）。細粒度の管理が必要な場合に使用。"]],"think":"「証拠書類は7年間保管義務」（コンプライアンス）があるなら、書類に封印（Retention Policy）をして誰も（管理者でも）破れないようにする。IAMで削除権限を取り消すだけでは管理者が権限を戻せる。ライフサイクルルールは削除するためのルールで逆効果。","vs":"IAMポリシーは管理者が変更できるため、真のimmutabilityにならない。ライフサイクルルールは削除を自動化するもので要件と逆。Cloud KMSは暗号化・アクセス制御でimmutabilityとは別の概念。","opt":["正解。Retention Policyで7年間の変更・削除禁止を設定できる。Lockedにすると管理者も変更不可。","IAMポリシーはロール付与の変更で管理者が権限を戻せるため真のimmutabilityにならない。","ライフサイクルルールは削除を自動化するもので「削除できない」要件とは逆の設定。","KMSはデータの暗号化・アクセス制御。オブジェクトのimmutability（変更不可）とは異なる目的。"]}'),

  ('m5q39', '監視・ログ',
   'Cloud Loggingのログを長期保存してコスト最適化しながらBigQueryでクエリできるようにしたい。どうすべきか？',
   NULL::text,
   '["Cloud LoggingでログシンクをBigQueryデータセットに向けて作成し、ログをBigQueryに自動エクスポートする","Cloud Loggingのデフォルト保存期間（30日）を延長してCloud Loggingのままログを保存する","Cloud LoggingからCloud StorageにログをエクスポートしてHadoopでクエリする","各VMのfluentdエージェントを設定して直接BigQueryにログを書き込む"]',
   0, '[0]', 'single',
   '{"asked":"Cloud LoggingのシンクでBigQueryへのログエクスポートを設定する方法を理解しているかを問う。ログの長期保存とSQLクエリのための標準的なアーキテクチャを知っているか。","terms":[["Cloud Logging シンク（Log Sink）","Cloud Loggingのログを他のサービス（BigQuery・GCS・Pub/Sub・Splunk等）に自動転送するルール。フィルタで特定のログだけを転送することも可能。"],["BigQuery ログ分析","Cloud LoggingシンクでBigQueryに送られたログはSQLでクエリ可能。長期保存コストがCloud Loggingより安く、複雑な分析に適する。"]],"think":"日々の記録（ログ）を長期保管するなら、整理された倉庫（BigQuery）に自動仕分け（ログシンク）で送る。Cloud Logging自体に長期間置くのはコストが高い。倉庫に送ってからSQLで好きな分析ができる。Hadoopは別のエコシステムで不要な手順が多い。","vs":"Cloud Loggingのストレージコストは長期保存では高くなる。Hadoop構成は必要以上に複雑。fluentdの直接BigQuery書き込みはエラー時のリトライ管理など信頼性の担保が大変でシンクより劣る。","opt":["正解。ログシンクでBigQueryへ自動エクスポート。長期保存とSQLクエリの両方を解決できる。","Cloud Loggingの長期保存はコスト増。また標準保存期間を延長する機能の上限がある（30日→3650日）が、BigQueryの方がコスト効率良く分析も可能。","Hadoop構成は管理コストが高くBigQueryで代替可能な分析に対して過剰。","fluentdの直接書き込みはCloud Loggingを経由しないため既存のログ転送・フィルタリングの仕組みが活かせない。"]}'),

  ('m5q42', 'IAM・組織ポリシー',
   'BigQueryデータウェアハウスをアナリストチームが使用しているが、クエリコストが高くなっている。ユーザーが1日に処理できるデータ量を制限したい。どうすべきか？',
   NULL::text,
   '["BigQueryでユーザーまたはプロジェクト単位のカスタムコスト管理（Custom Quota）を設定する","BigQueryのデータセットをアクセス制御でアナリストが読めないようにする","各アナリストに対してBigQueryのロールをViewerからDataViewerに変更する","データをパーティション分割してアナリストが必要な期間のみをクエリするよう教育する"]',
   0, '[0]', 'single',
   '{"asked":"BigQueryのカスタムコスト制御（Custom Quota）でユーザーやプロジェクトのデータ処理量を制限できることを理解しているかを問う。","terms":[["BigQuery Custom Quota（カスタムコスト管理）","プロジェクト単位またはユーザー単位で1日に処理できるデータ量の上限（バイト数）を設定する機能。オンデマンドクエリ料金のコスト管理に使用。","BigQuery IAMロール","BigQueryへのアクセス制御。roles/bigquery.dataViewerはデータの読み取り、roles/bigquery.userはジョブの実行権限を持つ。コスト制限とは別の機能。"]],"think":"会社の印刷機（BigQuery）の使いすぎ問題。各社員（ユーザー）の1日の印刷上限（カスタムコスト制御）を設定するのが直接的な解決策。アクセスを切るのは仕事ができなくなる。ロールの種類を変えても消費量の制限にはならない。教育は大事だが技術的な強制ではない。","vs":"データセットのアクセス制御はデータへのアクセス自体を制限するもので、クエリコスト制限ではない。BigQueryのロール変更（ViewerからDataViewer）はアクセス権の変更で、処理量の上限とは関係ない。パーティション教育は補助策として有効だが強制力がない。","opt":["正解。Custom Quotaでユーザー/プロジェクトのデータ処理量に上限を設けコストを直接制御できる。","アクセス制御を切るとアナリストが仕事できなくなる。コスト制限とアクセス制限は別の問題。","ロールの変更はアクセス権限の種類の変更で、処理データ量の上限設定とは異なる。","教育は効果的だが技術的な強制ではなく、過剰なクエリを防ぐ確実な手段にはならない。"]}'),

  ('m5q43', 'GKE',
   'GKEクラスタで動作するPodが別のGKEクラスタにあるPodとプライベートIPで通信する必要がある。同一GCPプロジェクト内にあるが、異なるVPCにある。どうすべきか？',
   NULL::text,
   '["2つのVPCをVPCピアリングで接続し、各クラスタのPod CIDRが重複しないことを確認する","Cloud VPNを2つのVPCの間に設定してIPsecトンネルを確立する","各クラスタをLoadBalancer Serviceで公開してパブリックIPアドレス経由で通信させる","GKEのMulti-cluster Gatewayを設定してクラスタ間のトラフィックを管理する"]',
   0, '[0]', 'single',
   '{"asked":"異なるVPCにあるGKEクラスタ間でプライベートIP通信を実現するためのVPCピアリングの使い方を理解しているかを問う。Pod CIDRの重複回避も重要なポイント。","terms":[["VPCピアリング（Pod CIDR考慮）","GKEのPodはVPC内のサブネットIPだけでなく、Pod CIDR（Podに割り当てるIPアドレス範囲）も持つ。ピアリングする際にはPod CIDR同士も重複させてはいけない。"],["GKE Multi-cluster Gateway","複数のGKEクラスタに対してトラフィックを振り分けるGateway機能。ただし、基盤となるネットワーク接続（VPCピアリング等）は別途必要。"]],"think":"2つの住宅地（VPC）の間に橋（VPCピアリング）を架けて住民（Pod）が行き来できるようにする。橋を架ける前に住所（Pod CIDR）が同じ番地を使っていないか確認する（重複チェック）。パブリックIP経由は橋ではなく国道（インターネット）を使うようなもので遅くなり余計なコストもかかる。","vs":"Cloud VPNも可能だが管理コストがピアリングより高い。パブリックIP通信は要件に反する。Multi-cluster Gatewayはトラフィックルーティングで基盤ネットワーク接続とは別。","opt":["正解。VPCピアリングで最小手順のプライベートIP通信を実現。Pod CIDR重複チェックが重要。","Cloud VPNも機能するが設定が複雑でピアリングより管理コストが高い。","パブリックIP経由はプライベートIP通信の要件に反し、セキュリティリスクも高まる。","Multi-cluster Gatewayはクラスタ間のトラフィック振り分けでネットワーク接続自体はピアリングが必要。"]}'),

  ('m5q44', 'ネットワーキング',
   'WebアプリケーションがSQLインジェクションやXSSなどのLayer 7攻撃を受けている。GCPでアプリを変更せずに保護したい。どうすべきか？',
   NULL::text,
   '["Cloud Armored WAF（Webアプリケーションファイアウォール）ルールをCloud Load Balancerのバックエンドサービスに適用する","VPCファイアウォールルールでHTTPポート（80/443）を全てブロックする","Cloud DNSのDNSSECを有効化してDNSベースの攻撃を防ぐ","Cloud Monitoringでアタックパターンを監視してアラートを設定する"]',
   0, '[0]', 'single',
   '{"asked":"Cloud ArmorのWAF機能でLayer 7の攻撃（SQLインジェクション、XSSなど）からWebアプリを保護できることを理解しているかを問う。","terms":[["Cloud Armor","GCPのDDoS保護とWAF（Webアプリケーションファイアウォール）サービス。Google Cloud Load Balancerのセキュリティポリシーとして設定。OWASP Top 10に対応した事前定義ルールを提供。"],["WAFルール（Pre-configured rules）","SQLインジェクション、XSS、リモートファイルインクルードなど、一般的なWebアタックを検出・ブロックする事前設定ルール。アプリを変更せずに保護が可能。"]],"think":"お店（Webアプリ）の前に凄腕のガードマン（Cloud Armor WAF）を置いて、危険な客（攻撃パターン）を入り口で追い返す。お店自体は何も変えない。VPCファイアウォールでHTTPを全ブロックは正常なユーザーも入れなくなる本末転倒。DNSSECはDNSの偽装攻撃対策でSQLiとは別の話。","vs":"VPCファイアウォールはIPレベルの制御でHTTPを全ブロックすると正当なユーザーもアクセスできなくなる。DNSSECはDNSセキュリティでLayer 7攻撃とは関係ない。Monitoringは事後検知でブロックはしない。","opt":["正解。Cloud Armor WAFルールでアプリ無修正のままSQLiやXSSをLayer 7でブロックできる。","HTTPポートを全ブロックはWebアプリが機能しなくなる。攻撃対策にはなっていない。","DNSSECはDNSレコードの改ざん防止でSQLインジェクション/XSSのLayer 7攻撃とは全く異なる問題。","Monitoringは攻撃の検知・通知で実際のブロックはできない。事後対応にしかならない。"]}'),

  ('m5q45', '運用・CLI',
   '開発・ステージング・本番の3環境に同じGCPリソース構成を一貫してデプロイしたい。リソースの設定差異を防ぎ、変更をコードで管理したい。どうすべきか？',
   NULL::text,
   '["TerraformやDeployment Managerなどのインフラストラクチャ・アズ・コード（IaC）ツールを使用してリソースを定義し、バージョン管理する","各環境をGCPコンソールから手動でセットアップし、設定内容をスプレッドシートで管理する","Cloud Shellスクリプトで各環境のgcloudコマンドを手動実行して設定する","既存の本番環境をエクスポートしてjsonファイルにして、他の環境に手動適用する"]',
   0, '[0]', 'single',
   '{"asked":"インフラストラクチャ・アズ・コード（IaC）の概念とGCPでの適用（Terraform/Deployment Manager）を理解しているかを問う。","terms":[["インフラストラクチャ・アズ・コード（IaC）","インフラの構成をコードで定義してバージョン管理するアプローチ。Terraform（HashiCorp）やGoogle Cloud Deployment Managerが代表例。複数環境への一貫したデプロイが可能。"],["Terraform","マルチクラウド対応のIaCツール。GCPのterraform providerを使ってほぼすべてのGCPリソースを定義できる。環境ごとにvariablesを変えるだけで同じ構成を複数環境に展開可能。"]],"think":"建物（インフラ）の設計図（IaCコード）をGit（バージョン管理）で管理すれば、同じ図面から3つのビル（開発/ステージング/本番）を一貫して建てられる。手作業で3棟建てると微妙に設計が違ってくる（環境差異）。スプレッドシートは動作するコードではなく自動化できない。","vs":"手動セットアップとスプレッドシート管理は設定差異が生じやすく自動化もできない。Cloud Shellスクリプトも可能だが冪等性の担保が難しい。JSONエクスポートは一部のリソースに限られる。","opt":["正解。IaCで環境の一貫性・バージョン管理・自動化を実現。インフラ変更のレビューも可能。","手動セットアップ+スプレッドシートは設定差異が生じやすく、スケールしない。","Cloud Shellスクリプトは冪等性（何度実行しても同じ結果になること）の担保が難しくIaCより信頼性が低い。","JSONエクスポートは一部リソースのみ対応でGCP全体のIaCとしては不完全。"]}'),

  ('m5q46', 'コンピュート・VM',
   'マネージドインスタンスグループ（MIG）でローリングアップデートを実行中に、途中でバグが見つかった。すでに一部のインスタンスが新バージョンになっている。以前のバージョンに素早く戻すには？',
   NULL::text,
   '["gcloud compute instance-groups managed rolling-action start-update --version=template=[旧バージョンテンプレート]でロールバックを実行する","新バージョンのインスタンスを1台ずつ手動で削除してMIGが旧テンプレートで再作成するのを待つ","MIGを一度削除して旧テンプレートで新しいMIGを再作成する","ロードバランサのバックエンドを切り替えて旧バージョンのMIGにトラフィックを戻す"]',
   0, '[0]', 'single',
   '{"asked":"MIGのローリングアップデートをロールバックする方法を理解しているかを問う。ロールバックも同じrolling-action update機能で実現できることを知っているか。","terms":[["MIG ロールバック","ローリングアップデートを旧バージョンのテンプレートを指定した新しいローリングアップデートとして実行する。gcloud compute instance-groups managed rolling-action start-updateコマンドを使用。"],["インスタンステンプレート（Instance Template）","MIGを作成するためのVMの設定テンプレート。バージョン管理のために複数テンプレートを保持しておくことでロールバックが可能になる。"]],"think":"工場の製品（VM）を新しい型（テンプレート）に切り替えていたら不良品が見つかった。同じ入れ替え機構（rolling-action update）を使って旧型（旧テンプレート）に戻す指示を出せばいい。手作業で製品を1つずつ壊すのは時間がかかる。工場自体を解体（MIG削除）するのは最悪の選択肢。","vs":"手動削除は時間がかかり運用コストが高い。MIG削除・再作成はリソースの全停止を意味する最悪の手段。別MIGへのLB切り替えは事前に旧バージョンMIGが必要で、ローリングアップデート中のロールバックには適さない。","opt":["正解。start-updateで旧テンプレートを指定してロールバックを実行。最速で最小ダウンタイム。","手動削除は時間がかかりスケールしない。特に多数のインスタンスがある場合は実用的でない。","MIGの削除は全インスタンスが停止し、再作成には時間がかかる。サービス停止が長時間に及ぶ。","事前に旧バージョンMIGを別に用意している場合のみ有効。ローリング中のロールバックには直接使えない。"]}'),

  ('m5q47', 'ストレージ',
   'Webサイトの静的コンテンツ（画像・CSS・JS）をCloud StorageとCloud CDNで配信している。世界中のユーザーへのレイテンシを最小化したい。どの設定が最も効果的か？',
   NULL::text,
   '["Cloud CDNのキャッシュモードをCACHE_ALL_STATICに設定し、適切なCache-Controlヘッダーをオブジェクトに付与する","Cloud StorageバケットをMulti-Regionalに変更する","CloudFrontなどのサードパーティCDNを追加で使用する","Cloud Load Balancerのグローバルエニーキャストを有効化するだけでキャッシュ設定は不要にする"]',
   0, '[0]', 'single',
   '{"asked":"Cloud CDNのキャッシュ設定とCache-Controlヘッダーを組み合わせてパフォーマンスを最大化する方法を理解しているかを問う。","terms":[["Cloud CDN キャッシュモード","CACHE_ALL_STATIC（静的コンテンツを自動的にキャッシュ）、USE_ORIGIN_HEADERS（オリジンのCache-Controlに従う）、FORCE_CACHE_ALL（全てをキャッシュ）などのモード。"],["Cache-Control ヘッダー","HTTPレスポンスでコンテンツのキャッシュ有効期限を指定するヘッダー（例：max-age=86400）。Cloud CDNはこのヘッダーに従ってエッジロケーションにコンテンツをキャッシュする。"]],"think":"コンビニ（CDN エッジ）に商品（静的コンテンツ）を補充するとき、賞味期限ラベル（Cache-Control）を付けることで店員（CDN）が「何日間補充しなくていいか」判断できる。Multi-Regionalはオリジンの地域分散でCDNキャッシュとは別の効果。CloudFrontはGCPと別系統で余計な複雑さを生む。","vs":"Multi-Regionalはオリジンの可用性向上でCDNキャッシュ最適化とは別の効果（多少は改善）。CloudFrontはAWSのサービスでGCPとの連携に追加設定が必要。グローバルエニーキャストはネットワーク最適化でキャッシュとは別機能。","opt":["正解。CACHE_ALL_STATIC + 適切なCache-ControlでCDNの効果を最大化し世界中のレイテンシを低減。","Multi-Regionalはオリジンの冗長性向上。CDNキャッシュ最適化には寄与するが、キャッシュ設定の方が効果大。","CloudFrontはAWSのCDN。GCPとの組み合わせは可能だが複雑さが増し、GCP CDNで同様の効果が得られる。","グローバルエニーキャストはLBのネットワーク最適化。CDNキャッシュなしではオリジンへのリクエストが多発しレイテンシ改善は限定的。"]}'),

  ('m5q49', 'データベース・データ分析',
   'IoTデバイスから毎秒数百万件のイベントデータがストリーミングで送信される。このデータをリアルタイムに集計・変換してBigQueryに保存したい。どのアーキテクチャが最適か？',
   NULL::text,
   '["IoTデバイス → Cloud Pub/Sub → Cloud Dataflow（ストリーミングパイプライン）→ BigQuery","IoTデバイス → Cloud Storage → bqコマンドで定期バッチロード → BigQuery","IoTデバイス → Compute Engine（カスタムアグリゲータ）→ BigQuery","IoTデバイス → Cloud Spanner → BigQueryフェデレーテッドクエリ"]',
   0, '[0]', 'single',
   '{"asked":"GCPのリアルタイムストリーミングデータ処理の標準的なアーキテクチャ（Pub/Sub + Dataflow + BigQuery）を理解しているかを問う。","terms":[["Cloud Pub/Sub","メッセージングサービス。IoTデバイスや分散システムからのイベントを非同期で受信・バッファリング。サブスクライバーが処理できるまでメッセージを保持する。"],["Cloud Dataflow","Apache Beamベースのフルマネージドデータ処理サービス。ストリーミング（リアルタイム）とバッチ処理の両方に対応。集計・変換・ウィンドウ処理などを大規模に実行できる。"],["ストリーミングパイプライン","リアルタイムデータを継続的に処理するパイプライン。Dataflowのストリーミングモードで実現。"]],"think":"工場（IoTデバイス）から来る部品（イベント）を、一時置き場（Pub/Sub）でバッファした後、組み立てライン（Dataflow）で加工して完成品（BigQuery）に登録するイメージ。Cloud Storageを経由するのはバッチ処理（翌朝まとめて）でリアルタイムではない。","vs":"Cloud Storage経由はバッチ処理でリアルタイムではない。Compute Engineカスタムアグリゲータは管理コストが高く大規模ストリーミングには不向き。Spannerはトランザクションデータベースでリアルタイムイベント集計には最適でない。","opt":["正解。Pub/Sub（受信・バッファ）+ Dataflow（変換・集計）+ BigQuery（保存）がGCPのリアルタイムストリーミング標準構成。","Cloud Storage経由はバッチ処理でリアルタイム要件を満たさない。","Compute Engineカスタムアグリゲータは運用が複雑で管理負荷が高い。GCPのマネージドサービスを活用すべき。","SpannerはOLTPデータベースで高頻度のストリーミングイベント集計には最適化されていない。BigQueryへの直接書き込みも毎秒百万件には非効率。"]}'),

  ('m5q50', 'データベース・データ分析',
   'Cloud Bigtableで時系列データ（センサーの計測値）を格納する。行キーにデバイスID+タイムスタンプ（昇順）を使っているがパフォーマンスが悪い。最も効果的な改善策は？',
   NULL::text,
   '["タイムスタンプを逆順（降順タイムスタンプ=Long.MAX_VALUE - timestamp）にすることでホットスポットを防ぎ最新データへのアクセスを高速化する","デバイスIDのみを行キーにしてタイムスタンプをカラム値として保存する","Bigtableのクラスタ数を増やして書き込みスループットを向上させる","BigQueryに移行してより良いタイムスタンプ処理を利用する"]',
   0, '[0]', 'single',
   '{"asked":"Cloud Bigtableの時系列データにおける行キー設計のベストプラクティス（逆順タイムスタンプ）を理解しているかを問う。タイムスタンプ昇順がホットスポットを生む理由を知っているか。","terms":[["逆順タイムスタンプ（Reverse Timestamp）","Bigtableの時系列データで、タイムスタンプをLong.MAX_VALUE - timestampとして行キーに含める手法。最新データが行キーの先頭に来るので、最新N件の取得が高速。書き込みの分散にも効果的。"],["Bigtableホットスポット","書き込みが特定の行範囲（タブレット）に集中する現象。昇順タイムスタンプは常に最大値付近に書き込みが集中するためホットスポットになる。"]],"think":"センサーの記録を日付ページ（タイムスタンプ昇順）で管理すると、最後のページ（最新日）に全員が書き込みに来て渋滞（ホットスポット）が起きる。ページ番号を逆読み（逆順タイムスタンプ）にすると、最新データほど前のページになり検索しやすく、書き込みも分散される。","vs":"デバイスIDのみではタイムスタンプ順の範囲スキャンができなくなる。クラスタ増加はスループット向上に寄与するが根本のホットスポット問題は解決しない。BigQueryへの移行は大規模アーキテクチャ変更でBigtableの強みを捨てることになる。","opt":["正解。逆順タイムスタンプでホットスポットを解消し、最新データへの高速アクセスも実現できる。","デバイスIDのみの行キーでは同一デバイスのデータを時系列でスキャンできなくなる。","クラスタ増加はスケールアップだが昇順タイムスタンプのホットスポット問題は根本解決できない。","BigQueryはOLAP向けでBigtableの超低レイテンシ・高スループットという特性が必要なユースケースに合わない。"]}'
  )

) AS v(source_ref, cat_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.cat_name
WHERE s.slug = 'gcp-ace'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
